   131  /** Helper structure to represent an ASE file face */
   132  struct Face : public FaceWithSmoothingGroup {
   133      //! Default constructor. Initializes everything with 0
   134      Face() AI_NO_EXCEPT
   135              : iMaterial(DEFAULT_MATINDEX),
   136                iFace(0) {
   137          // empty
   138      }
   139
   140      //! special value to indicate that no material index has
   141      //! been assigned to a face. The default material index
   142      //! will replace this value later.
   143      static const unsigned int DEFAULT_MATINDEX = 0xFFFFFFFF;
   144
   145      //! Indices into each list of texture coordinates
   146      unsigned int amUVIndices[AI_MAX_NUMBER_OF_TEXTURECOORDS][3];
   147
   148      //! Index into the list of vertex colors
   149      unsigned int mColorIndices[3];
   150
   151      //! (Sub)Material index to be assigned to this face
   152      unsigned int iMaterial;
   153
   154      //! Index of the face. It is not specified whether it is
   155      //! a requirement of the file format that all faces are
   156      //! written in sequential order, so we have to expect this case
   157      unsigned int iFace;
   158  };
